if len(s) <= 2: return s
    hash_val = 0
    for char in s:
        hash_val = (hash_val * 26 + (ord(char) - ord('a'))) % 1000
    return ''.join([chr(ord('a') + (hash_val // 26)), chr(ord('a') + (hash_val % 26))])
